import React, { useEffect, useState } from "react";
import { Trash2 } from "lucide-react";
import toast from "react-hot-toast";
import Helpers from "../Helper/Helpers";
import Swal from "sweetalert2";

const OrderList = () => {
  const [orders, setOrders] = useState([]);
  const [dateFilter, setDateFilter] = useState("all");

  useEffect(() => {
    fetchAllOrders();
  }, []);

  const fetchAllOrders = async () => {
    const res = await Helpers(`/admin/order/`, "GET");
    if (res && res?.status) {
      setOrders(res?.data);
    } else {
      toast.error("Failed to fetch orders");
    }
  };

  const handleDeleteOrder = async (id) => {
    const result = await Swal.fire({
      title: "Are you sure you want to delete this order?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Yes, delete it!",
    });

    if (result.isConfirmed) {
      const res = await Helpers(`/admin/order/${id}`, "DELETE");
      if (res && res?.status) {
        toast.success("Order deleted successfully");
        fetchAllOrders();
      } else {
        toast.error("Failed to delete order");
      }
    }
  };

  const filteredOrders = orders.filter((order) => {
    const createdAt = new Date(order.createdAt);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(today.getDate() - 1);
    const oneWeekAgo = new Date();
    oneWeekAgo.setDate(today.getDate() - 7);
    const twoWeeksAgo = new Date();
    twoWeeksAgo.setDate(today.getDate() - 14);
    const oneMonthAgo = new Date();
    oneMonthAgo.setMonth(today.getMonth() - 1);

    switch (dateFilter) {
      case "today":
        return createdAt.toDateString() === today.toDateString();
      case "yesterday":
        return createdAt.toDateString() === yesterday.toDateString();
      case "one-week":
        return createdAt >= oneWeekAgo;
      case "two-weeks":
        return createdAt >= twoWeeksAgo && createdAt < oneWeekAgo;
      case "one-month":
        return createdAt >= oneMonthAgo;
      default:
        return true;
    }
  });

  return (
    <div className="max-w-7xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6 text-center text-gray-800">
        Order List
      </h1>

      {/* Date Filter */}
      <div className="mb-6">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Filter by date:
        </label>
        <select
          value={dateFilter}
          onChange={(e) => setDateFilter(e.target.value)}
          className="w-full md:w-1/3 px-4 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring focus:border-blue-500"
        >
          <option value="all">All Dates</option>
          <option value="today">Today</option>
          <option value="yesterday">Yesterday</option>
          <option value="one-week">Last 1 Week</option>
          <option value="two-weeks">Last 2 Weeks</option>
          <option value="one-month">Last 1 Month</option>
        </select>
      </div>

      {/* Order Cards */}
      <div className="grid sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredOrders.length > 0 ? (
          filteredOrders.map((order) => (
            <div
              key={order._id}
              className="bg-white rounded-xl shadow-lg border hover:shadow-2xl transition-shadow duration-300"
            >
              <div className="p-5">
                <div className="flex justify-between items-center mb-3">
                  <h2 className="text-lg font-bold text-gray-800">
                    Order ID: {order._id.substring(0, 8)}...
                  </h2>
                  <button
                    onClick={() => handleDeleteOrder(order._id)}
                    className="text-red-600 hover:text-red-800"
                    title="Delete Order"
                  >
                    <Trash2 size={20} />
                  </button>
                </div>

                <div className="mb-2">
                  <p className="text-sm text-gray-600 font-medium mb-1">
                    Customer:
                  </p>
                  <p className="text-gray-800">
                    {order.userDetails.firstName} {order.userDetails.lastName}
                  </p>
                </div>

                <div className="mb-2">
                  <p className="text-sm text-gray-600 font-medium mb-1">
                    Phone:
                  </p>
                  <p className="text-gray-800">{order.userDetails.phone}</p>
                </div>

                <div className="mb-2">
                  <p className="text-sm text-gray-600 font-medium mb-1">
                    Email:
                  </p>
                  <p className="text-gray-800">{order.userDetails.email}</p>
                </div>

                <div className="mb-2">
                  <p className="text-sm text-gray-600 font-medium mb-1">
                    Address:
                  </p>
                  <p className="text-gray-800">
                    {order.userDetails.streetAddress}, {order.userDetails.city},{" "}
                    {order.userDetails.state}, {order.userDetails.pinCode}
                  </p>
                </div>

                <div className="mb-2">
                  <p className="text-sm text-gray-600 font-medium mb-1">
                    Total Amount:
                  </p>
                  <p className="text-gray-800 font-semibold">₹{order.total}</p>
                </div>

                <div className="mb-4">
                  <p className="text-sm text-gray-600 font-medium mb-1">
                    Date:
                  </p>
                  <p className="text-gray-800">
                    {new Date(order.createdAt).toLocaleDateString()}
                  </p>
                </div>

                {/* Product List */}
                <div className="border-t pt-4">
                  <p className="text-sm font-semibold text-gray-700 mb-2">
                    Products:
                  </p>
                  <div className="space-y-2 max-h-44 overflow-y-auto">
                    {order?.product.map((product, idx) => (
                      <div
                        key={idx}
                        className="flex items-center gap-3 bg-gray-100 p-2 rounded-md"
                      >
                        <img
                          src={product?.images[0]}
                          alt={product?.name}
                          className="w-10 h-10 rounded object-cover"
                        />
                        <div className="flex-1">
                          <p className="text-sm font-medium text-gray-800">
                            {product?.name}
                          </p>
                          <p className="text-xs text-gray-600">
                            Qty: {product?.quantity} × ₹{product?.price}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))
        ) : (
          <p className="text-center text-gray-500">No orders available.</p>
        )}
      </div>
    </div>
  );
};

export default OrderList;
