import React, { useState, useEffect } from "react";
import { toast } from "react-hot-toast";
import Helpers from "../Helper/Helpers";
import Swal from "sweetalert2";
const Categoryfile = () => {
  const [users, setUsers] = useState([]);
  const [status, setStatus] = useState(true);
  const [name, setName] = useState("");
  const [id, setId] = useState("");

  useEffect(() => {
    FetchAllCategory();
  }, []);

  const FetchAllCategory = async () => {
    try {
      const res = await Helpers("/admin/category/get", "GET");
      if (res && res?.status) {
        setUsers(res?.data?.reverse());
        // console.log("fdfdfdfdfd", res?.data);
      } else {
      }
    } catch (error) {
      console.log(error);
    }
  };

  const handleUpdate = (user) => {
    setStatus(false);
    setName(user?.name);
    setId(user?._id);
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();
    if (name) {
      let data = {
        name: name,
      };
      try {
        const res = await Helpers("/admin/category/add", "POST", data);
        if (res && res?.status) {
          toast.success("Category Added Successfully.");
          setName("");
          FetchAllCategory();
        } else {
          toast.error("Failed to add category.");
        }
      } catch (error) {
        console.log(error);
      }
    } else {
      toast?.error("Category field is required");
    }
  };

  const handleUpdateCategory = async (e) => {
    e.preventDefault();

    if (name) {
      let data = {
        name: name,
      };
      try {
        const res = await Helpers(`/admin/category/update/${id}`, "PUT", data);
        if (res && res?.status) {
          toast.success("Category Updated Successfully.");
          setName("");
          FetchAllCategory();
          setStatus(true);
        } else {
          toast.error("Failed to update category.");
        }
      } catch (error) {
        console.log(error);
      }
    } else {
      toast?.error("Category field is required");
    }
  };

  const handleDeleteUser = async (id) => {
    const result = await Swal.fire({
      title: "Are you sure?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Yes, delete it!",
    });

    if (result.isConfirmed) {
      const res = await Helpers(
        `/admin/deleteadminaccount/${id}`,
        "DELETE",
        {}
      );
      if (res && res?.status) {
        toast.success("Deleted Successfully");
        FetchAllCategory();
      } else {
        toast?.error("Deletion failed");
      }
    }
  };

  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 5;

  // Calculate the indexes for slicing the users array
  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = users.slice(indexOfFirstUser, indexOfLastUser);

  // Pagination control functions
  const handleNextPage = () => {
    if (currentPage < Math.ceil(users.length / usersPerPage)) {
      setCurrentPage(currentPage + 1);
    }
  };

  const handlePrevPage = () => {
    if (currentPage > 1) {
      setCurrentPage(currentPage - 1);
    }
  };

  return (
    <div className="p-8">
      <h1 className="text-3xl font-bold mb-8">
        {status ? "Add" : "Update"} Category
      </h1>
      <div className="mb-8 flex flex-col items-center">
        {" "}
        {/* Centering content horizontally */}
        <h2 className="text-xl font-semibold mb-9">
          {" "}
          {status ? "Add" : "Update"} Category
        </h2>{" "}
        {/* Added margin for spacing */}
        <div className="flex flex-wrap gap-4 md:gap-8 lg:gap-14">
          {/* Input fields */}
          <input
            type="text"
            placeholder="Category Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="border p-2 rounded w-full md:w-64 lg:w-72"
            style={{ border: "1px solid gray" }}
          />

          <button
            onClick={status ? handleAddCategory : handleUpdateCategory}
            className="bg-blue-500 text-white p-2 rounded w-full md:w-auto"
          >
            {status && currentUsers?.length <= 3 ? "Submit" : "Update"}
          </button>
        </div>
      </div>
      {/* Users Table */}
      <h2 className="text-xl font-semibold mb-9 flex">Manage Category</h2>{" "}
      <div className="bg-white shadow-md rounded-lg p-6">
        <div className="overflow-x-auto">
          <table className="w-full table-auto min-w-[600px]">
            <thead>
              <tr className="bg-gray-200 text-left">
                <th className="p-4">ID</th>
                <th className="p-4">Category Name</th>
                <th className="p-4">Actions</th>
              </tr>
            </thead>
            <tbody>
              {currentUsers.map((user, index) => (
                <tr key={user.id}>
                  <td className="p-4">{indexOfFirstUser + index + 1}</td>
                  <td className="p-4">{user.name}</td>
                  <td className="p-4 flex gap-2">
                    <button
                      onClick={() => handleUpdate(user)}
                      className="bg-blue-500 text-white p-2 rounded"
                    >
                      Edit
                    </button>

                    {/* <button
                      onClick={() => handleDeleteUser(user._id)}
                      className="bg-red-500 text-white p-2 rounded"
                    >
                      Delete
                    </button> */}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {/* Pagination controls */}
        <div className="flex justify-between items-center mt-4">
          <button
            onClick={handlePrevPage}
            disabled={currentPage === 1}
            className="bg-blue-500 text-white p-2 rounded disabled:bg-gray-300"
          >
            Previous
          </button>
          <span>
            Page {currentPage} of {Math.ceil(users.length / usersPerPage)}
          </span>
          <button
            onClick={handleNextPage}
            disabled={currentPage >= Math.ceil(users.length / usersPerPage)}
            className="bg-blue-500 text-white p-2 rounded disabled:bg-gray-300"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
};

export default Categoryfile;
